export function LiElement({
  item1 = "{{item1}}",
  item2 = "{{item2}}",
  item3 = "{{item3}}",
  accent = "{{accent}}",
  markStatus = {{markStatus}},
}) {
  const itemStyle = { "::marker": { color: accent } };
  return (
    <ol style={{ width: 260, boxSizing: "border-box", font: "14px/1.7 system-ui, sans-serif", color: "#241430", background: "#FAF7F2", padding: "16px 16px 16px 34px", borderRadius: 12, margin: 0 }}>
      <li>{item1}</li>
      <li>{item2}</li>
      <li style={markStatus ? { textDecoration: "line-through", color: "#241430888" } : undefined}>{item3}</li>
    </ol>
  );
}
